import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/KOLMOGOROV_002dSMIRNOV.md","filePath":"manual-en/KOLMOGOROV_002dSMIRNOV.md","lastUpdated":1785684581000}'),n={name:"manual-en/KOLMOGOROV_002dSMIRNOV.md"};function r(s,e,d,m,l,O){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h4 id="_15-12-6-kolmogorov-smirnov-test" tabindex="-1">15.12.6 Kolmogorov-Smirnov Test <a class="header-anchor" href="#_15-12-6-kolmogorov-smirnov-test" aria-label="Permalink to &quot;15.12.6 Kolmogorov-Smirnov Test&quot;">​</a></h4><pre><code>     [ /KOLMOGOROV-SMIRNOV ({NORMAL [mu, sigma], UNIFORM [min, max], POISSON [lambda], EXPONENTIAL [scale] }) = var_list ]
</code></pre><p>The one-sample Kolmogorov-Smirnov subcommand is used to test whether or not a dataset is drawn from a particular distribution. Four distributions are supported, <em>viz:</em> Normal, Uniform, Poisson and Exponential.</p><p>Ideally you should provide the parameters of the distribution against which you wish to test the data. For example, with the normal distribution the mean (mu)and standard deviation (sigma) should be given; with the uniform distribution, the minimum (min)and maximum (max) value should be provided. However, if the parameters are omitted they are imputed from the data. Imputing the parameters reduces the power of the test so should be avoided if possible.</p><p>In the following example, two variables score and age are tested to see if they follow a normal distribution with a mean of 3.5 and a standard deviation of 2.0.</p><pre><code>  NPAR TESTS
        /KOLMOGOROV-SMIRNOV (normal 3.5 2.0) = score age.
</code></pre><p>If the variables need to be tested against different distributions, then a separate subcommand must be used. For example the following syntax tests score against a normal distribution with mean of 3.5 and standard deviation of 2.0 whilst age is tested against a normal distribution of mean 40 and standard deviation 1.5.</p><pre><code>  NPAR TESTS
        /KOLMOGOROV-SMIRNOV (normal 3.5 2.0) = score
        /KOLMOGOROV-SMIRNOV (normal 40 1.5) =  age.
</code></pre><p>The abbreviated subcommand <code>K-S</code> may be used in place of <code>KOLMOGOROV-SMIRNOV</code>.</p>`,9)])])}const h=a(n,[["render",r]]);export{u as __pageData,h as default};
